pub const fn shen_q1(ctx: &Ctx) -> f32 {
    ((((0.02) + (0.005 * (ctx.q_level - 1f32)))
        + ((0.015) * (ctx.ability_power * 0.01)))
        * ctx.enemy_max_health)
        + (match ctx.level as u8 {
            ..4 => 10f32,
            4..7 => 16f32,
            7..10 => 22f32,
            10..13 => 28f32,
            13..16 => 34f32,
            16.. => 40f32,
        })
}

pub const fn shen_q2(ctx: &Ctx) -> f32 {
    ((((0.05) + (0.005 * (ctx.q_level - 1f32)))
        + ((0.02) * (ctx.ability_power * 0.01)))
        * ctx.enemy_max_health)
        + (match ctx.level as u8 {
            ..4 => 10f32,
            4..7 => 16f32,
            7..10 => 22f32,
            10..13 => 28f32,
            13..16 => 34f32,
            16.. => 40f32,
        })
}

pub const fn shen_q3(ctx: &Ctx) -> f32 {
    ((((0.15) + (0.015 * (ctx.q_level - 1f32)))
        + ((0.06) * (ctx.ability_power * 0.01)))
        * ctx.enemy_max_health)
        + (match ctx.level as u8 {
            ..4 => 30f32,
            4..7 => 48f32,
            7..10 => 66f32,
            10..13 => 84f32,
            13..16 => 102f32,
            16.. => 120f32,
        })
}

pub const fn shen_q4(ctx: &Ctx) -> f32 {
    ((((0.06) + (0.015 * (ctx.q_level - 1f32)))
        + ((0.045) * (ctx.ability_power * 0.01)))
        * ctx.enemy_max_health)
        + (match ctx.level as u8 {
            ..4 => 30f32,
            4..7 => 48f32,
            7..10 => 66f32,
            10..13 => 84f32,
            13..16 => 102f32,
            16.. => 120f32,
        })
}

pub const fn shen_e1(ctx: &Ctx) -> f32 {
    5f32 * (12f32 + 0.022 * ctx.bonus_health + 5f32 * (-1f32 + ctx.e_level))
}

